function drawSlash(f){const at=AT[f.av||0];if(!at||f.t<at.a0-1||f.t>at.a1+4)return;const u=cl((f.t-at.a0+1)/(at.a1-at.a0+5),0,1);X.save();X.translate(f.x,FY+f.z-f.y-30);X.scale(f.dir,1);X.lineCap='round';X.globalAlpha=1-u*.6;const r=(at.f1||100)*.72*(f.S.ar||1);X.strokeStyle='#202A32';X.lineWidth=9;X.beginPath();X.ellipse(3,0,r,r*.55,-.4,-1.2+u*.8,1.4+u*.6);X.stroke();X.strokeStyle='#C6E6F6';X.lineWidth=5;X.stroke();X.restore()}
