const Reveal={cancel:null};
function gAnim(res,nAgain){if(Reveal.cancel)Reveal.cancel();const o=$('gani'),focus=document.activeElement,reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let finished=false,timer=null;const exit=()=>{cancel();o.hidden=true;if(focus&&focus.isConnected)focus.focus({preventScroll:true})},cancel=()=>{clearTimeout(timer);removeEventListener('keydown',keys,true);Reveal.cancel=null},finish=()=>{if(finished)return;finished=true;clearTimeout(timer);$('reveal-stage').hidden=true;$('reveal-grid').hidden=false;$('reveal-actions').hidden=false;$('reveal-skip').textContent='結果已保存';$('reveal-skip').disabled=true;$('reveal-exit').focus();SFX.loot()},keys=e=>{if(o.hidden)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();finished?exit():finish()}else if((e.code==='Enter'||e.code==='Space')&&!e.target.closest('button')){e.preventDefault();e.stopImmediatePropagation();finish()}};Reveal.cancel=cancel;o.hidden=false;o.setAttribute('role','dialog');o.setAttribute('aria-label','幸運轉蛋結果');o.innerHTML=`<div class="reveal-shell"><header class="reveal-top"><div><small>LUCKY DRAW / ADVENTURE ISLAND</small><h2>${res.some(r=>r.rare===2)?'好運，真的來了。':'新的收藏，新的可能。'}</h2></div><button class="quiet" id="reveal-skip">跳過演出</button></header><p class="reveal-caption">本次獎勵已保存。跳過與關閉不會再次發獎。</p><div class="capsule-stage" id="reveal-stage"><div class="capsule"></div></div><div class="reveal-grid" id="reveal-grid" hidden>${res.map((r,i)=>{const icon=/寵物/.test(r.t)?'star':/神獸/.test(r.t)?'shield':/裝備|〔/.test(r.t)?'sword':/碎片/.test(r.t)?'dust':'coin';const receipt=RUI.drops.find(d=>r.t.includes(d.n));return `<article class="reveal-card ${r.rare?'rare':''}" style="--rarity:${r.c};animation-delay:${Math.min(i,10)*.035}s">${RUI.icon(icon,45)}<b>${esc(r.t)}</b><small>${r.disposition||(receipt?receipt.result:res.length===1&&RUI.lastLoot?.name&&r.t.includes(RUI.lastLoot.name)?RUI.lastLoot.result:r.rare?'稀有獎勵':'已保存至帳號')}</small></article>`}).join('')}</div><div class="reveal-actions" id="reveal-actions" hidden>${nAgain?`<button class="primary" id="reveal-again">再抽 ${nAgain} 次 →</button>`:''}<button class="quiet" id="reveal-exit">返回冒險</button></div></div>`;$('reveal-skip').onclick=finish;$('reveal-exit').onclick=exit;if($('reveal-again'))$('reveal-again').onclick=()=>{cancel();o.hidden=true;doGacha(nAgain)};addEventListener('keydown',keys,true);$('reveal-skip').focus();if(reduce)finish();else timer=setTimeout(finish,1200)}
function showModal(o){const previous=document.activeElement;stopHold();holdStop();$('ic').textContent=o.ic;$('mh').textContent=o.h;$('msub').textContent=o.sub||'';$('gs').innerHTML=(o.g||[]).map(([v,l])=>`<div><b>${v}</b><small>${l}</small></div>`).join('');$('rec').innerHTML=o.note||'';const btns=$('btns');btns.innerHTML='';for(const [label,action,primary]of o.btns){const b=document.createElement('button');b.textContent=label;if(primary)b.className='pri';b.onclick=()=>{$('ov').classList.remove('show');if(previous?.isConnected)previous.focus({preventScroll:true});action&&action()};btns.append(b)}$('card').setAttribute('role','dialog');$('card').setAttribute('aria-modal','true');$('card').setAttribute('aria-labelledby','mh');$('ov').classList.add('show');setTimeout(()=>btns.querySelector('button')?.focus(),0)}

function panelScroll(id){const p=$(id);if(!p)return;for(const e of[p,...p.querySelectorAll('.rows,.inv,.list,[data-scroll]')])e.scrollTop=0;if(RUI.ready){p.tabIndex=-1;p.focus({preventScroll:true});if(G){$('advanced-host').scrollTop=0}else scrollTo(0,0)}}
function drawSp(f){const t=f.t,k=f.spk,c=f.spc||'#B9DFF6',A=f.S?.area||1,x=f.x,y=FY+f.z-f.y;X.save();X.lineCap='round';X.lineJoin='round';if(k==='proj'&&t<8){Art.ellipse(x+f.dir*24,y-30,8+t*2,8+t*2,c,Art.ink,2);Art.line([[x+f.dir*16,y-30],[x+f.dir*35,y-30]],'#F3F6F8',2)}else if(k==='dash'&&t>=2&&t<=18){X.globalAlpha=1-Math.max(0,t-14)/5;for(let i=0;i<3;i++)Art.line([[x-f.dir*(25+i*8),y-10-i*16],[x-f.dir*(130+i*12),y-10-i*16]],c,4-i);X.globalAlpha*=.22;Art.path(()=>{X.moveTo(x,y-57);X.quadraticCurveTo(x-f.dir*65,y-37,x-f.dir*165,y-32);X.quadraticCurveTo(x-f.dir*60,y-18,x,y+1)},c,null)}else if(k==='up'&&t>=2&&t<=26){X.globalAlpha=t<20?1:1-(t-20)/6;for(let i=0;i<5;i++){const yy=y-i*29;X.strokeStyle=i%2?c:'#E5F0F5';X.lineWidth=3;X.beginPath();X.ellipse(x+f.dir*45,yy,(30+i*7)*A,6,0,t*.15+i,t*.15+i+4.1);X.stroke()}}else if(k==='aoe'){for(const start of[6,11,16]){const u=(t-start)/14;if(u<0||u>1)continue;X.globalAlpha=1-u;Art.ellipse(x,FY+f.z,185*A*Math.sqrt(u),74*A*Math.sqrt(u),null,c,3+3*(1-u))}if(t>=4&&t<=24){X.globalAlpha=.5;Art.line([[x,y-165],[x,y-10]],c,5)}}X.restore()}
function drawUlt(f){const t=f.t,kind=f.ut,c=f.spc||'#B9DFF6',x=f.x,y=FY+f.z;X.save();X.lineCap='round';X.lineJoin='round';if(t<16){Art.ellipse(x,y,Math.max(2,90-t*5),Math.max(1,(90-t*5)*.35),null,c,3)}else if(kind==='beam'){const alpha=t>70?Math.max(0,1-(t-70)/12):.9;X.globalAlpha=alpha;Art.line([[x-470,y-35],[x+470,y-35]],Art.ink,16);Art.line([[x-470,y-35],[x+470,y-35]],c,10);Art.line([[x-470,y-35],[x+470,y-35]],'#E7F0F5',3);for(let i=0;i<3;i++)Art.ellipse(x+(i-1)*230,y-35,12,35+i*5,null,c,3)}else if(kind==='storm'){for(let i=0;i<(GQ?18:8);i++){const age=t-(14+i*2);if(age<0||age>18)continue;const px=x+(hsh(i,1)-.5)*720,py=y-30+(hsh(i,2)-.5)*145;X.globalAlpha=1-age/18;Art.line([[px-55,py+25],[px+55,py-25]],Art.ink,6);Art.line([[px-55,py+25],[px+55,py-25]],c,3.5)}}else if(kind==='blizzard'){for(let i=0;i<(GQ?16:7);i++){const age=t-(14+i*3);if(age<0||age>28)continue;const px=x+(hsh(i,4)-.5)*720,py=-30+age*15;X.globalAlpha=Math.min(1,age/5);Art.path(()=>{X.moveTo(px-7,py-40);X.lineTo(px+5,py-45);X.lineTo(px+9,py+4);X.lineTo(px,py+18);X.lineTo(px-9,py+1);X.closePath()},'#BADDEB',Art.ink,1.5)}}else if(kind==='meteor'){for(let i=0;i<(GQ?10:5);i++){const age=t-(16+i*4);if(age<0||age>30)continue;const px=x+(hsh(i,5)-.5)*760+age*2,py=-100+age*17;X.globalAlpha=Math.min(1,age/4);Art.line([[px-25,py-85],[px,py]],'#DCA17C',8);Art.ellipse(px,py,12,15,'#B78063',Art.ink,2)}}else{for(const start of[18,30,42,54]){const u=(t-start)/24;if(u<0||u>1)continue;X.globalAlpha=1-u;Art.ellipse(x,y,80+u*360,28+u*125,null,c,7*(1-u)+1);for(let i=0;i<4;i++){const xx=x+(i-1.5)*90;Art.path(()=>{X.moveTo(xx-20,y);X.quadraticCurveTo(xx-6,y-60*(1-u),xx+12,y);X.closePath()},c,Art.ink,1.5)}}}if(t>=UFIN){const u=(t-UFIN)/Math.max(1,UEND-UFIN);X.globalAlpha=1-u;Art.ellipse(x,y,u*650,u*220,null,c,5*(1-u)+1)}X.restore()}
function miniMap(me){if(!me)return;const x=263,y=52,w=215,h=12,Z=zones(),sx=w/G.ww;X.save();Art.box(x,y,w,h,3,'#E3EDF2',Art.ink,1);X.strokeStyle='#7D919E';X.lineWidth=.8;for(let i=1;i<Z.n;i++)Art.line([[x+Z.w*i*sx,y],[x+Z.w*i*sx,y+h]],'#A8BBC6',.8);X.strokeStyle='#24658B';X.strokeRect(x+G.cam*sx,y,VW*sx,h);for(const item of G.items)if(['rune','lun','portal'].includes(item.k))Art.box(x+item.x*sx-2,y+4,4,4,1,item.k==='portal'?'#C8A45F':'#9F85BD',null);for(const f of G.F){if(f.dead)continue;const xx=x+f.x*sx,yy=y+2+f.z/ZM*(h-4);if(f.isP)Art.ellipse(xx,yy,2.1,2.1,f===me?'#202A32':'#24658B',null);else Art.box(xx-1,yy-1,f.boss?4:2,f.boss?4:2,1,f.boss?'#A77E3D':'#AC6876',null)}X.restore()}
function goalHud(){if(!G||G.over)return;const left=Math.max(0,G.need-Math.floor(G.prog||0));let text=G.wb?'30秒內打出最高傷害':G.asl?'兩人在3秒內各擊破一顆水晶，讓BOSS破防':G.raid?'限時內打倒遠征BOSS':G.clr?'過關！':G.bossOn?'打倒魔王就能突破':`再討伐 ${left} 隻，魔王出現`;if(!G.raid&&!G.mid&&!G.goldm&&!G.bossOn)text+=` · ${Math.max(0,Math.ceil(G.need*.5)-Math.floor(G.prog||0))} 隻後出現菁英與寶箱`;X.save();X.font='800 10px "Microsoft JhengHei",sans-serif';X.textAlign='left';X.strokeStyle='#F3F6F8';X.lineWidth=3;X.strokeText(text,14,88);X.fillStyle='#202A32';X.fillText(text,14,88);X.restore()}
function dPr(p){const y=FY+p.z-p.y-32,c=p.col||'#B9DFF6';X.save();X.lineCap='round';X.lineJoin='round';if(p.kind==='bomb'){const gy=FY+p.z;Art.ellipse(p.x,gy,p.r,p.r/2.2,'#B9384625','#B93846',2);Art.ellipse(p.x,gy-11,9,9,'#5A5155');Art.line([[p.x+3,gy-19],[p.x+6,gy-26]],'#C3A26B',2)}else{X.translate(p.x,y);X.scale(p.vx>=0?1:-1,1);if(p.kind==='arrow'){Art.line([[-22,0],[8,0]],'#7F6750',2.4);Art.path(()=>{X.moveTo(13,0);X.lineTo(5,-4);X.lineTo(5,4);X.closePath()},'#C7D9E2',Art.ink,1.3);Art.line([[-21,-4],[-17,0],[-21,4]],'#A7786D',2)}else if(p.kind==='bullet'){Art.line([[-24,0],[4,0]],'#D9B77B',3);Art.ellipse(5,0,4,2.5,'#E9D6B0',Art.ink,1)}else if(p.kind==='star'){X.rotate(FR*.4);Art.path(()=>{for(let i=0;i<8;i++){const a=i*Math.PI/4,r=i%2?3:8;i?X.lineTo(Math.cos(a)*r,Math.sin(a)*r):X.moveTo(Math.cos(a)*r,Math.sin(a)*r)}X.closePath()},'#BCCDD8',Art.ink,1.3)}else if(p.kind==='wave'){const r=p.r||15;Art.path(()=>{X.moveTo(-r*2,-r*.4);X.quadraticCurveTo(r,-r*1.5,r,0);X.quadraticCurveTo(r,r*1.5,-r*2,r*.4);X.quadraticCurveTo(-r*.6,0,-r*2,-r*.4)},c,Art.ink,2);Art.line([[-r,0],[r*.5,0]],'#E7F0F5',2)}else if(p.kind==='knife')Art.line([[-10,0],[10,0]],c,3);else{Art.ellipse(0,0,Math.max(2,p.r||6),Math.max(2,(p.r||6)*.7),c,Art.ink,1.5);Art.line([[-16,0],[-8,0]],c,2)}}X.restore()}
function drawPortals(){const Z=zones();for(let i=0;i<Z.n;i++){const x=Z.w*(i+.5);if(x<G.cam-55||x>G.cam+VW+55)continue;X.save();X.lineCap='round';Art.ellipse(x,FY+4,24,7,'#B9DFF655',Art.ink,1.5);Art.ellipse(x,FY-25,17,29,'#567A91','#202A32',3);Art.ellipse(x,FY-25,12,23,null,'#B9DFF6',2.2);X.strokeStyle='#E6F2F7';X.lineWidth=2;X.beginPath();X.ellipse(x,FY-25,9,18,0,FR*.04,FR*.04+3);X.stroke();X.fillStyle=Art.ink;X.font='800 9px sans-serif';X.textAlign='center';X.fillText('傳送點 '+(i+1),x,FY-62);X.restore()}}
function dItem(it){const x=it.x,y=FY+it.z-it.y;X.save();X.lineJoin='round';X.lineCap='round';Art.ellipse(x,FY+it.z+1,9,3,'#202A3225',null);if(it.k==='coin'){X.translate(x,y-7);X.scale(Math.max(.2,Math.abs(Math.cos(FR*.1+x))),1);Art.ellipse(0,0,6,7,'#D9BC73',Art.ink,1.4);Art.line([[0,-3],[0,3]],'#786134',1.3)}else if(it.k==='gear'){const ri=it.ri??it.it.ri,sl=it.sl||it.it?.sl||'w',col=RAR[ri][1];if(ri>=2&&GQ>0){X.globalAlpha=.25;Art.box(x-5,y-(55+ri*13),10,55+ri*13,4,col,null);X.globalAlpha=1}X.drawImage(itemIconC(sl,ri,it.it?.anc),x-13,y-25,26,26);Art.line([[x-11,y+3],[x+11,y+3]],col,3)}else if(it.k==='portal'){Art.ellipse(x,FY+it.z-28,19,30,'#4C597A',Art.ink,3);Art.ellipse(x,FY+it.z-28,13,23,null,'#D2BB73',2);X.fillStyle=Art.ink;X.textAlign='center';X.font='800 10px sans-serif';X.fillText('隱藏關卡 · '+Math.ceil(it.life/60)+'s',x,FY+it.z-66)}else if(it.k==='rune'||it.k==='lun'){const color=it.k==='lun'?'#B4A2CD':RUNE[it.rt||it.ri]?.[2]||'#B9DFF6';Art.path(()=>{X.moveTo(x,y-32);X.lineTo(x+10,y-22);X.lineTo(x+7,y-6);X.lineTo(x-7,y-6);X.lineTo(x-10,y-22);X.closePath()},color,Art.ink,2);X.fillStyle=Art.ink;X.textAlign='center';X.font='900 11px sans-serif';X.fillText(it.k==='lun'?'輪':(RUNE[it.rt||it.ri]||RUNE.atk)[3],x,y-15)}else{Art.box(x-4,y-18,8,5,1,'#D4DDE1',Art.ink,1.3);Art.ellipse(x,y-7,7,8,it.k==='hp'?'#D28A94':'#8EB8D6',Art.ink,1.5);Art.line([[x-3,y-9],[x-2,y-6]],'#E7F1F6',1.5)}X.restore()}
function dFx(p){if(p.x!==undefined&&!['bt','bm','lv','sk'].includes(p.t)&&(p.x<G.cam-260||p.x>G.cam+VW+260))return;X.save();X.lineJoin='round';X.lineCap='round';const c=p.col||'#B9DFF6',reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(p.t==='p'||p.t==='em'){X.globalAlpha=Math.min(.8,p.l/(p.t==='em'?(p.l0||20):12));Art.ellipse(p.x,p.y,Math.max(.5,p.r||2),Math.max(.5,p.r||2),c,null)}else if(p.t==='sh'){X.globalAlpha=Math.min(1,p.l/10);X.translate(p.x,p.y);X.rotate(p.a||0);Art.box(-(p.r||3)/2,-(p.r||3)/2,p.r||3,(p.r||3)*.7,1,c,null)}else if(p.t==='d'){X.globalAlpha=Math.min(.25,p.l/30);Art.ellipse(p.x,p.y,(p.r||3)*(1+(26-p.l)*.05),(p.r||3)*.7,'#C6BAA7',null)}else if(p.t==='s'||p.t==='hs'){const u=1-p.l/(p.t==='hs'?9:12),r=(p.s||p.r||15)*(.35+u*.7);X.globalAlpha=1-u*.8;X.translate(p.x,p.y);X.rotate(p.a||0);Art.path(()=>{X.moveTo(-r,0);X.quadraticCurveTo(0,-4*(1-u),r,0);X.quadraticCurveTo(0,4*(1-u),-r,0)},c,null);Art.ellipse(0,0,r*.4,r*.4,null,c,1.6)}else if(p.t==='bt'){X.globalAlpha=p.l/p.l0;const points=[[p.x1,p.y1]];for(let i=1;i<7;i++){const u=i/7;points.push([p.x1+(p.x2-p.x1)*u+(hsh(i,p.l)-.5)*10,p.y1+(p.y2-p.y1)*u+(hsh(i+1,p.l)-.5)*10])}points.push([p.x2,p.y2]);Art.line(points,Art.ink,5*(p.w||1));Art.line(points,c,2.5*(p.w||1))}else if(p.t==='bm'){const u=p.l/p.l0,h=p.h*Math.min(1,u/.8);X.globalAlpha=Math.min(.65,u*1.5);Art.box(Math.min(p.x,p.x+p.w),p.y-h,Math.abs(p.w),h*2,Math.min(7,h),c,null);Art.line([[p.x,p.y],[p.x+p.w,p.y]],'#F3F6F8',2)}else if(p.t==='r'){const u=1-p.l/p.l0;X.globalAlpha=(1-u)*.8;Art.ellipse(p.x,p.y,p.r*u,p.r*u*.4,null,c,3*(1-u)+1)}else if(p.t==='g'){if(!reduced){X.globalAlpha=p.l/12*.2;Art.char(p.ap,p.pp,p.dir,p.sc,0,p.x,FY+p.z-p.y,'sp')}}else if(p.t==='sk'){X.globalAlpha=Math.min(1,p.l/14);X.font='900 16px "Microsoft JhengHei",sans-serif';X.textAlign='center';X.strokeStyle='#F3F6F8';X.lineWidth=3;X.strokeText(p.txt,p.x,p.y-(1-p.l/56)*15);X.fillStyle=Art.ink;X.fillText(p.txt,p.x,p.y-(1-p.l/56)*15)}else if(p.t==='lv'){const u=1-p.l/60;X.globalAlpha=1-u;Art.ellipse(p.x,FY+p.z,25+u*60,(25+u*60)*.35,null,'#B9DFF6',3);if(!reduced)for(let i=0;i<3;i++)Art.line([[p.x-18+i*18,FY+p.z-20-u*50],[p.x-18+i*18,FY+p.z-35-u*50]],'#B9DFF6',3)}else if(p.t==='n'){const critical=p.sty==='c',size=critical?26:p.sty==='lv'?22:18,pop=p.age<5?1+.25*(1-p.age/5):1;X.translate(p.x,p.y);X.scale(pop,pop);X.globalAlpha=Math.min(1,p.l/12);X.font=`900 ${size}px "Arial Black","Microsoft JhengHei",sans-serif`;X.textAlign='center';X.strokeStyle=Art.ink;X.lineWidth=4;X.strokeText(p.txt,0,0);X.fillStyle={n:'#F3F0D6',c:'#F0B6C5',p:'#D9C3E8',h:'#BDE0C9',m:'#B9DFF6',lv:'#D6E8B8'}[p.sty]||'#F3F6F8';X.fillText(p.txt,0,0);if(critical){X.font='900 9px sans-serif';X.strokeText('CRITICAL',0,-24);X.fillText('CRITICAL',0,-24)}}X.restore()}
function drawTele(f){if(f.st!=='bsp')return;const k=(f.bk||'').split(':')[0],I=BKN[k],t=f.t;X.save();X.lineJoin='round';if(I&&t<I[1]&&(f.boss||f.elite))(G.tl2||(G.tl2=[])).push([f.x-G.cam,Math.max(150,FY+f.z-f.y-(f.c.fly?60:90)*f.sc-18),`⚠ ${I[0]} ${Math.max(0,(I[1]-t)/60).toFixed(1)}s`,I[2],t/I[1],t]);const geoms=Art.warningGeometry(f);if(k==='nova'&&geoms.length){const outer=geoms[0].values,inner=geoms[1].values;X.beginPath();X.ellipse(...outer,0,0,Math.PI*2);X.ellipse(...inner,0,0,Math.PI*2);X.fillStyle='#B938463A';X.fill('evenodd')}else for(const g of geoms){if(g.safe)continue;const[x,y,a,b]=g.values;X.fillStyle='#B9384635';if(g.shape==='ellipse'){X.beginPath();X.ellipse(x,y,a,b,0,0,Math.PI*2);X.fill()}else X.fillRect(x,y,a,b)}if(k==='fan'&&t<30){Art.line([[f.x+f.dir*25,FY+f.z-f.y-35],[f.x+f.dir*60,FY+f.z-f.y-35]],'#8C303A',3);Art.line([[f.x+f.dir*52,FY+f.z-f.y-41],[f.x+f.dir*60,FY+f.z-f.y-35],[f.x+f.dir*52,FY+f.z-f.y-29]],'#8C303A',3)}X.restore()}
